(() => {
  const mq=window.matchMedia('(max-width:780px)');
  let moreOpen=false;
  function addStyles(){if(document.getElementById('srMobileSmartStyles'))return;const e=document.createElement('style');e.id='srMobileSmartStyles';e.textContent=`
    .mobile-only{display:none}.mobile-bottom-nav,.mobile-fab,.mobile-more-sheet,.mobile-filter-toggle{display:none}
    @media(max-width:780px){
      :root{--mobile-nav-h:66px}
      body{padding-bottom:calc(var(--mobile-nav-h) + env(safe-area-inset-bottom));overscroll-behavior-y:none}
      .desktop-only{display:none!important}.mobile-only{display:block}
      .top{position:sticky;top:0;padding:9px 10px;min-height:58px;z-index:45;align-items:center}
      .brand{gap:7px;min-width:0}.mark{width:36px;height:36px;border-radius:11px;font-size:13px;flex:0 0 auto}.brand strong{font-size:13px;white-space:nowrap}.brand span{display:none}
      .top-actions{gap:5px;flex-wrap:nowrap}.top-actions .mode{display:none}.top-actions .field{min-width:0!important;width:116px}.top-actions .field span{display:none}.top-actions select{height:36px;padding:6px 26px 6px 8px;font-size:11px;border-radius:10px}.top-actions #newBtn{display:none}
      .shell{padding:9px 9px 12px;max-width:none}.kpis{display:flex;overflow-x:auto;gap:8px;scroll-snap-type:x proximity;padding:1px 1px 5px;margin:0 -1px}.kpis::-webkit-scrollbar{display:none}.kpi{min-width:145px;padding:10px;scroll-snap-align:start}.kpi strong{font-size:19px}.kpi small{font-size:10px}
      .filters{padding:10px;margin-top:7px;display:none;border-radius:13px}.filters.mobile-open{display:flex}.filters .field,.filters .field.search{min-width:100%;width:100%}.filters .chips{overflow-x:auto;flex-wrap:nowrap;padding-bottom:2px}.filters .chip{white-space:nowrap}
      .mobile-filter-toggle{display:flex;width:100%;justify-content:space-between;align-items:center;margin-top:7px;padding:10px 12px;border:1px solid var(--line);background:var(--panel);border-radius:13px;box-shadow:var(--shadow);font-weight:650;color:var(--text)}
      .workspace{display:block;margin-top:8px}.side{display:none!important}.project-grid{display:flex;overflow-x:auto;gap:8px;scroll-snap-type:x mandatory;margin:0 -9px;padding:2px 9px 7px}.project-grid::-webkit-scrollbar{display:none}.project{min-width:82vw;max-width:82vw;scroll-snap-align:center;border-radius:14px;padding:11px}.project .service{min-height:auto}.project:hover{transform:none}
      .main{margin-top:6px;padding:12px;border-radius:15px;min-height:calc(100vh - 250px);box-shadow:none}.panel-head{gap:7px}.panel-title{font-size:16px}.panel-sub{font-size:11px}.panel-actions{width:100%;display:grid;grid-template-columns:1fr 1fr}.panel-actions .btn{padding:9px 8px}
      .metrics{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:9px 0}.metric{padding:9px;border-radius:11px}.metric strong{font-size:16px}.detail{display:block}.detail>.box{margin-bottom:8px}.box{padding:10px;border-radius:12px}.listrow{padding:9px 0;align-items:flex-start}.listrow .btn{flex:0 0 auto}.tabs{overflow-x:auto;flex-wrap:nowrap;padding-bottom:4px}.tabs::-webkit-scrollbar{display:none}.tab{white-space:nowrap}
      .table-wrap{margin-left:-4px;margin-right:-4px;border-radius:10px}.table{min-width:720px}.risk{grid-template-columns:1.5fr .4fr .4fr .7fr .5fr;min-width:560px}
      .modal{z-index:70}.modal-card{left:0;right:0;bottom:0;top:auto;transform:none;width:100%;max-height:92dvh;border-radius:20px 20px 0 0;padding-bottom:env(safe-area-inset-bottom)}.modal-head{position:sticky;top:0;background:#fff;z-index:2;border-radius:20px 20px 0 0}.modal-foot{position:sticky;bottom:0;background:#fff;z-index:2}.modal-body{padding:12px}.wizard{display:flex;overflow-x:auto;gap:5px}.step{min-width:105px;padding:7px 8px}.formgrid{grid-template-columns:1fr}.field{min-width:0}
      #srMap{height:58dvh!important;min-height:360px;border-radius:12px}.map-grid{display:flex!important;flex-direction:column}.map-tools{order:-1}.map-drop{padding:10px}.map-stat{grid-template-columns:1fr 1fr}.map-tools>.box{max-height:180px;overflow:auto}
      .mobile-bottom-nav{position:fixed;display:grid;grid-template-columns:repeat(5,1fr);left:0;right:0;bottom:0;height:calc(var(--mobile-nav-h) + env(safe-area-inset-bottom));padding:5px 5px env(safe-area-inset-bottom);background:rgba(255,255,255,.97);backdrop-filter:blur(14px);border-top:1px solid var(--line);z-index:60;box-shadow:0 -8px 24px rgba(17,42,54,.08)}
      .mobile-bottom-nav button{border:0;background:transparent;color:var(--muted);font-size:9px;border-radius:10px;padding:4px 2px;display:grid;place-items:center;gap:1px}.mobile-bottom-nav button i{font-style:normal;font-size:20px;line-height:22px}.mobile-bottom-nav button.active{color:var(--accent);background:#eef6f8;font-weight:700}
      .mobile-fab{display:grid;place-items:center;position:fixed;right:15px;bottom:calc(var(--mobile-nav-h) + 15px + env(safe-area-inset-bottom));width:52px;height:52px;border-radius:50%;border:0;background:var(--accent);color:#fff;font-size:26px;box-shadow:0 10px 28px rgba(23,107,135,.35);z-index:59}
      .mobile-more-sheet{display:none;position:fixed;left:8px;right:8px;bottom:calc(var(--mobile-nav-h) + 7px + env(safe-area-inset-bottom));background:#fff;border:1px solid var(--line);border-radius:18px;padding:8px;z-index:61;box-shadow:0 18px 52px rgba(15,42,54,.24)}.mobile-more-sheet.open{display:grid;grid-template-columns:1fr 1fr;gap:5px}.mobile-more-sheet button{border:0;background:var(--soft);padding:13px 10px;border-radius:12px;text-align:left;color:var(--text)}
      .business-mobile-table .table-wrap{max-height:none!important}.business-mobile-table .table{min-width:980px}
      .callout{font-size:11px}
    }
    @media(max-width:390px){.project{min-width:88vw;max-width:88vw}.top-actions .field{width:104px}.kpi{min-width:132px}.metrics{grid-template-columns:1fr 1fr}}
  `;document.head.appendChild(e)}

  function createUi(){
    if(!document.getElementById('mobileFilterToggle')){const filters=document.querySelector('.filters');if(filters){const b=document.createElement('button');b.id='mobileFilterToggle';b.className='mobile-filter-toggle';b.innerHTML='<span>⌕ Buscar y filtrar</span><span id="mobileFilterState">Mostrar</span>';filters.insertAdjacentElement('beforebegin',b);b.onclick=()=>{filters.classList.toggle('mobile-open');const open=filters.classList.contains('mobile-open');document.getElementById('mobileFilterState').textContent=open?'Ocultar':'Mostrar'}}}
    if(!document.getElementById('mobileFab')){const b=document.createElement('button');b.id='mobileFab';b.className='mobile-fab';b.type='button';b.setAttribute('aria-label','Nuevo proyecto');b.textContent='＋';b.onclick=()=>document.getElementById('newBtn')?.click();document.body.appendChild(b)}
    if(!document.getElementById('mobileBottomNav')){const n=document.createElement('nav');n.id='mobileBottomNav';n.className='mobile-bottom-nav';n.innerHTML=`<button data-mobile-sec="negocios"><i>◎</i><span>Negocios</span></button><button data-mobile-sec="panel"><i>▦</i><span>Proyectos</span></button><button data-mobile-sec="acciones"><i>✓</i><span>Acciones</span></button><button data-mobile-sec="mapa"><i>⌖</i><span>Mapa</span></button><button data-mobile-more><i>•••</i><span>Más</span></button>`;document.body.appendChild(n);n.querySelectorAll('[data-mobile-sec]').forEach(b=>b.onclick=()=>go(b.dataset.mobileSec));n.querySelector('[data-mobile-more]').onclick=()=>toggleMore()}
    if(!document.getElementById('mobileMoreSheet')){const d=document.createElement('div');d.id='mobileMoreSheet';d.className='mobile-more-sheet';d.innerHTML=`<button data-mobile-sec="control">◆ Control / Gates</button><button data-mobile-sec="operacion">⚙ Operación técnica</button><button data-mobile-sec="direccion">◉ Dirección</button><button data-mobile-sec="documentos">▤ Documentos</button><button data-mobile-sec="alertas">⚠ Alertas</button><button id="mobileRoleButton">👤 Cambiar rol</button>`;document.body.appendChild(d);d.querySelectorAll('[data-mobile-sec]').forEach(b=>b.onclick=()=>go(b.dataset.mobileSec));d.querySelector('#mobileRoleButton').onclick=()=>{toggleMore(false);document.getElementById('role')?.focus();document.querySelector('.top')?.scrollIntoView({behavior:'smooth'})}}
    sync();
  }
  function go(sec){toggleMore(false);const btn=document.querySelector(`#nav [data-sec="${sec}"]`);if(btn){btn.click()}else if(typeof s!=='undefined'){s.section=sec;try{renderAll()}catch(_){try{renderNav();renderMain()}catch(__){}}}sync();window.scrollTo({top:0,behavior:'smooth'})}
  function toggleMore(force){moreOpen=typeof force==='boolean'?force:!moreOpen;document.getElementById('mobileMoreSheet')?.classList.toggle('open',moreOpen)}
  function sync(){if(!mq.matches)return;document.querySelectorAll('#mobileBottomNav [data-mobile-sec]').forEach(b=>b.classList.toggle('active',typeof s!=='undefined'&&s.section===b.dataset.mobileSec));const more=document.querySelector('#mobileBottomNav [data-mobile-more]');if(more)more.classList.toggle('active',typeof s!=='undefined'&&['control','operacion','direccion','documentos','alertas'].includes(s.section));const market=document.getElementById('main');if(market)market.classList.toggle('business-mobile-table',typeof s!=='undefined'&&s.section==='negocios')}
  function smartHeader(){if(!mq.matches)return;const role=document.getElementById('role');if(role)role.setAttribute('aria-label','Vista de rol')}
  function watch(){const obs=new MutationObserver(()=>{sync();smartHeader()});obs.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});mq.addEventListener?.('change',()=>{createUi();sync()})}
  addStyles();createUi();smartHeader();watch();
  document.addEventListener('click',e=>{if(moreOpen&&!e.target.closest('#mobileMoreSheet')&&!e.target.closest('[data-mobile-more]'))toggleMore(false)});
  window.SmartRiskMobile={go,sync,get isMobile(){return mq.matches}};
})();